 import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, smoothstep, mix, color as colorNode } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, Mesh, PlaneGeometry, Color, FrontSide } = THREE;

  const root = new Group();

  const colors = config.intent?.visualSpec?.colors ?? config.colors ?? {};
  const ink = colors.ink ?? '#16161d';
  const paper = colors.paper ?? '#e8ecf2';
  const accent = colors.accent ?? '#ff2a38';
  const surface = colors.surface ?? '#0b0b10';
  const imageUrl = config.imageUrl ?? '/prism-assets/chrome/ceramic-grain.map.png';

  // --- stage backdrop ---
  const bgGeo = new PlaneGeometry(7, 6);
  const gradUv = uv();
  const grad = colorNode(surface).mix(colorNode(ink), smoothstep(0, 1, gradUv.y));
  const bgMat = new MeshBasicNodeMaterial({ side: FrontSide });
  bgMat.colorNode = grad;
  const bgMesh = new Mesh(bgGeo, bgMat);
  bgMesh.position.z = -2.5;
  root.add(bgMesh);

  // --- badge subject ---
  const subject = new Group();
  root.add(subject);

  const edgeW = 1.8;
  const edgeH = 0.62;
  const edgeGeo = new PlaneGeometry(edgeW, edgeH);
  const edgeMat = new MeshBasicNodeMaterial({
    color: new Color(accent),
    transparent: true,
    opacity: 0.45,
    side: FrontSide,
    depthWrite: false
  });
  const edgeMesh = new Mesh(edgeGeo, edgeMat);
  edgeMesh.position.z = -0.02;
  subject.add(edgeMesh);

  const badgeW = 1.6;
  const badgeH = 0.5;
  const badgeGeo = new PlaneGeometry(badgeW, badgeH);
  const badgeMat = new MeshBasicNodeMaterial({
    color: new Color(paper),
    side: FrontSide
  });
  const badgeMesh = new Mesh(badgeGeo, badgeMat);
  subject.add(badgeMesh);

  // --- texture load ---
  let disposed = false;
  if (ctx.textureLoader && imageUrl) {
    ctx.textureLoader.loadTexture(imageUrl).then((tex) => {
      if (disposed || !tex) return;
      tex.colorSpace = THREE.SRGBColorSpace;
      badgeMat.map = tex;
      badgeMat.needsUpdate = true;
    }).catch(() => {});
  }

  // --- cinematic primitives (none expected, but loop handles any) ---
  const primitiveRuns = [];
  for (const primitive of (config.cinematicPrimitives ?? [])) {
    if (ctx.primitives && typeof ctx.primitives[primitive.name] === 'function') {
      primitiveRuns.push(ctx.primitives[primitive.name](root, primitive.params));
    }
  }

  // --- interaction handlers ---
  const baseY = 0;
  const hoverLift = 0.15;
  let hoverT;
  let outT;
  let pressT;
  let releaseT;

  function killActiveMotion() {
    if (hoverT) hoverT.kill();
    if (outT) outT.kill();
    if (pressT) pressT.kill();
    if (releaseT) releaseT.kill();
    gsap.killTweensOf(root.position);
    gsap.killTweensOf(root.scale);
    gsap.killTweensOf(edgeMat);
  }

  function onHover() {
    killActiveMotion();
    hoverT = gsap.to(root.position, {
      y: baseY + hoverLift,
      duration: 0.35,
      ease: 'power2.out'
    });
    gsap.to(edgeMat, { opacity: 0.85, duration: 0.35, ease: 'power2.out' });
  }

  function onHoverEnd() {
    killActiveMotion();
    outT = gsap.to(root.position, {
      y: baseY,
      duration: 0.5,
      ease: 'power2.out'
    });
    gsap.to(edgeMat, { opacity: 0.45, duration: 0.5, ease: 'power2.out' });
  }

  function onPress() {
    pressT = gsap.to(root.scale, {
      x: 0.97,
      y: 0.97,
      z: 0.97,
      duration: 0.12,
      ease: 'back.out'
    });
  }

  function onRelease() {
    releaseT = gsap.to(root.scale, {
      x: 1,
      y: 1,
      z: 1,
      duration: 0.25,
      ease: 'power2.out'
    });
  }

  function onClick() {
    onPress();
    gsap.delayedCall(0.12, () => {
      onRelease();
      ctx.emit('hub-collection.select', { id: config.id, source: config });
    });
  }

  root.userData.handlers = {
    hover: onHover,
    pointerover: onHover,
    pointerout: onHoverEnd,
    pointerdown: onPress,
    pointerup: onRelease,
    click: onClick
  };

  root.userData.cleanup = () => {
    disposed = true;
    killActiveMotion();
    for (const run of primitiveRuns) {
      if (run && typeof run.cleanup === 'function') run.cleanup();
    }
    for (const mesh of [bgMesh, edgeMesh, badgeMesh]) {
      if (!mesh) continue;
      mesh.geometry.dispose();
      if (mesh.material.map) mesh.material.map.dispose();
      mesh.material.dispose();
    }
  };

  return root;
}
